from pathlib import Path
import re,base64,html
root=Path('C:/Programings/2026_2_창의학기제')
old=(root/'output/presentations/WeGoTrip_HTML_PDF/WeGoTrip_정산_준비물.html').read_text(encoding='utf8')
css=re.search(r'<style>(.*?)</style>',old,re.S).group(1)
js=re.search(r'<script>(.*?)</script>',old,re.S).group(1).replace("document.querySelector('#print').onclick=()=>print();",'')
gantt='<img class="" src="data:image/png;base64," alt="프로젝트 일정. 7행 실시간 그룹 채팅 기능 추가의 7주차 완료 체크" data-source="gantt" tabindex="0">'
slides=[]
def slide(title,body,cl=''):
 slides.append(f'<section class="slide {cl}" aria-label="{len(slides)+1}. {title}"><header><h2>{title}</h2></header>{body}<footer><span>We Go Trip · 10조</span><span>{len(slides)+1:02d} / TOTAL</span></footer></section>')
def img(name):
 data=base64.b64encode((Path('C:/Users/user/Downloads')/name).read_bytes()).decode()
 return f'<img src="data:image/png;base64,{data}" alt="{name}" data-source="{name}" tabindex="0">'
def block(t,p):return f'<div class="text-block"><h3>{t}</h3><p>{p}</p></div>'
def pair(a,b,copy):return '<div class="ui-pair-layout"><div class="phones">'+img(a)+img(b)+'</div><div class="copy">'+copy+'</div></div>'
def entity(name,desc,rows):
 return '<div class="entity"><h3>'+name+'</h3><p class="entity-desc">'+desc+'</p><table>'+''.join(f'<tr><td><code>{f}</code></td><td>{d}</td></tr>' for f,d in rows)+'</table></div>'
slide('We Go Trip','''<div class="cover-body"><div><h1>We Go Trip</h1><p class="cover-sub">여행 통합 관리 앱 · 기능 구현 발표</p><p class="team">10조<br><span>2026.10.25</span></p></div><div class="cover-index"><div><b>01</b><span>실시간 채팅과 사진 공유</span></div><div><b>02</b><span>함께 결정하는 투표</span></div><div><b>03</b><span>여행 공지와 알림</span></div></div></div>''','cover')
slide('이번 구현의 핵심','''<div class="overview"><div><span class="num">01</span><h3>대화와 사진</h3><p>여행 전체·파티별 채팅<br>여러 사진 선택과 전송</p></div><div><span class="num">02</span><h3>투표</h3><p>단일·복수 선택<br>장소 연결과 자동 마감</p></div><div><span class="num">03</span><h3>여행 공지</h3><p>방장이 작성하고<br>모든 멤버가 확인</p></div></div><div class="statement">여행 중 나누는 대화와 결정 사항을 한곳에서 공유</div>''')
slide('프로젝트 일정','<div class="gantt-wrap">'+gantt+'</div>')
slide('여행 전체와 파티별 대화','<div class="ui-layout"><div class="copy">'+block('채팅방 선택','전체 채팅과 참여 중인 파티 채팅을<br>상단에서 전환')+block('대화 안에서 함께 공유','텍스트·사진·투표를 같은 대화 흐름에 표시')+block('이전 대화 확인','최신 50개를 먼저 표시하고<br>이전 메시지를 추가로 조회')+'</div><div class="phone-single">'+img('채팅 화면.png')+'</div></div>')
slide('여러 사진 전송과 이미지 모아보기',pair('사진 선택 화면.png','이미지만 필터링.png',block('선택한 순서대로 전송','사진 여러 장을 고르고<br>한 번에 전송')+block('이미지 메시지만 조회','이미지 필터를 켜면<br>현재 채팅방의 사진만 표시')+'<div class="callout">사진을 누르면 크게 확인</div><p class="desc">실패한 사진은 선택을 유지해 재시도</p>'))
slide('투표 만들기',pair('투표 추가1.png','투표 추가2.png',block('질문과 선택 항목','2~10개 항목을 등록하고<br>단일 선택 또는 복수 선택 설정')+block('여행 장소 연결','저장된 장소를 선택 항목에 연결')+block('자동 마감 설정','빠른 시간 선택 또는<br>날짜·시간 직접 입력')))
slide('채팅 안에서 투표 참여','<div class="poll-layout"><div class="poll-shot">'+img('투표 채팅내 화면.png')+'</div><div class="copy">'+block('선택과 취소','선택한 항목을 다시 누르면 취소<br>같은 항목에는 한 번만 투표')+block('결과를 바로 확인','항목별 득표 수와 비율 표시<br>참여 인원은 사람별로 집계')+block('마감 후 변경 제한','서버가 마감 시각을 판단<br>작성자 또는 접근 가능한 방장이 수동 마감')+'</div></div>')
slide('여행 공지 작성과 고정',pair('공지 화면.png','공지작성 화면.png',block('방장이 관리하는 공지','작성·수정·삭제·고정은 방장만<br>현재 여행 멤버는 모두 조회')+block('중요한 공지는 상단에','고정 공지를 먼저 표시하고<br>같은 조건에서는 최신순 정렬')+'<div class="callout">새 공지 등록 시 멤버에게 알림</div><p class="desc">수정·고정 변경·삭제는 추가 알림 제외</p>'))
slide('실시간 대화 반영 흐름','''<div class="flow-intro">WebSocket으로 변경을 알리고, 인증된 API로 최신 내용을 조회</div><div class="flow"><div><b>01</b><h3>메시지 저장</h3><p>서버 권한 검사 후<br>DB에 저장</p></div><span>→</span><div><b>02</b><h3>변경 이벤트</h3><p>접근 가능한 멤버에게<br>WebSocket 전달</p></div><span>→</span><div><b>03</b><h3>최신 내용 조회</h3><p>HTTP로 메시지·투표 조회<br>화면에 반영</p></div></div><div class="two-notes"><div><h3>연결 중단 시 복구</h3><p>재접속과 주기적 조회로 놓친 변경 확인</p></div><div><h3>여행 공지 갱신</h3><p>목록 진입·앱 복귀·새로고침 시 조회</p></div></div>''')
slide('채팅 메시지와 이미지 저장','<div class="db-two">'+entity('chat_message','대화의 기본 단위',[('id','메시지 ID'),('trip_id / party_id','여행·파티 범위'),('author_id / kind','작성자·메시지 종류'),('text','텍스트 본문'),('image_upload_id','업로드 참조')])+'<div class="db-link">이미지 참조<br><strong>→</strong></div>'+entity('chat_image_upload','이미지 업로드 정보',[('id','업로드 ID'),('trip_id / party_id','업로드한 채팅방'),('author_id','업로드 사용자'),('public_id / image_url','Cloudinary 참조·URL'),('claimed','메시지 연결 여부')])+'</div><div class="statement">이미지 파일은 Cloudinary에, URL과 연결 정보는 DB에 저장</div><p class="note">party_id가 NULL이면 전체 채팅 · 업로드 사용자와 채팅방이 일치하는 이미지만 첨부</p>')
slide('투표와 항목별 선택 저장','<div class="db-three">'+entity('chat_poll','투표 설정',[('id / message_id','투표·메시지 연결'),('question','투표 질문'),('allow_multiple','복수 선택 여부'),('closed / closes_at','마감 상태·시각')])+entity('chat_poll_option','선택 가능한 항목',[('id / poll_id','항목·투표 연결'),('label','항목 이름'),('saved_place_id','여행 장소 연결'),('place_name / place_address','생성 당시 장소 정보')])+entity('chat_poll_vote','멤버의 선택 기록',[('poll_id','참여한 투표'),('option_id','선택한 항목'),('user_id','투표한 사용자')])+'</div><div class="relation-line">투표 1개 <strong>—</strong> 여러 항목 <strong>—</strong> 항목별 선택 기록</div><div class="statement">투표 + 사용자 + 항목 조합을 고유하게 저장해 중복 선택 방지</div><p class="note">연결한 장소를 삭제해도 투표 생성 당시 장소 이름과 주소는 보존</p>')
slide('여행 공지 데이터와 변경 관리','<div class="notice-db">'+entity('trip_notice','여행별 공지 저장',[('id / trip_id','공지 ID·소속 여행'),('author_id','작성자'),('title / body','제목·본문'),('pinned','상단 고정 여부'),('version','수정 버전'),('created_at / updated_at','작성·수정 시각')])+'<div class="copy">'+block('공지 내용과 상태 저장','여행 멤버가 다른 기기에서도<br>같은 공지를 조회')+block('오래된 변경 요청 차단','요청한 버전과 현재 버전을 비교<br>내용이 바뀌었다면 최신 내용 확인 안내')+'<div class="callout">여행 공지는 trip_notice에서 관리</div><p class="desc">개인 알림용 notification과 분리</p></div></div>')
slide('채팅과 공지의 접근 권한','''<div class="access"><div><span>01</span><h3>전체 채팅</h3><p>현재 여행 멤버만 조회·작성·구독</p></div><div><span>02</span><h3>파티 채팅</h3><p>해당 파티 멤버만 접근<br>방장도 파티 밖에서는 접근 불가</p></div><div><span>03</span><h3>여행 공지</h3><p>모든 여행 멤버가 조회<br>작성·수정·삭제·고정은 방장만 가능</p></div><div><span>04</span><h3>탈퇴·여행 종료</h3><p>탈퇴 이후 접근·구독·알림 차단<br>종료·보관된 여행은 조회만 허용</p></div></div><div class="statement">화면 표시와 별개로, 서버가 요청마다 현재 권한을 검사</div>''')
slide('공통 푸시 알림과 발송 기록','<div class="push-top"><p>새 채팅·이미지·투표·공지를 알리고, 알림을 누르면 해당 화면으로 이동</p></div><div class="db-two push-db">'+entity('push_event','알림 발생과 수신 대상',[('event_type / source_id','종류·원본 ID'),('targets_json','수신 대상 기록'),('expires_at','발송 유효기간')])+'<div class="db-link">1 : N<br><strong>→</strong></div>'+entity('push_delivery','기기별 발송과 재시도',[('event_id / device_id','이벤트·기기 연결'),('status / attempts','발송 상태·시도 수'),('next_attempt_at','다음 재시도 시각')])+'</div><div class="two-notes push-notes"><div><h3>발송 직전 다시 확인</h3><p>현재 권한·알림 설정·기기 토큰 검사<br>작성자 자신의 기기는 제외</p></div><div><h3>실패 시 재시도</h3><p>기본 24시간 이내, 최대 7회 시도<br>잠금 화면에는 원문 대신 기본 안내</p></div></div><p class="note">FCM 접수는 기기 표시·열람을 의미하지 않으며, 실기기 푸시 수신은 추가 확인이 필요</p>')
